EMBEDDED_VAULT = {
  "v": 1,
  "kdf": "pbkdf2-hmac-sha256-200k",
  "salt": "ssLrAkNE9lxKI7CNUCrUQQ==",
  "iv": "FAN6Bl76NHV6MiFFmyxsaQ==",
  "ct": "",
  "mac": "4apT13y16wWfVO+563H0AXrM19rCUF5cRQHtDivopq4="
}

def _keystream_xor(data: bytes, enc_key: bytes, iv: bytes) -> bytes:
    out = bytearray(len(data))
    block_count = (len(data) + 31) // 32
    for counter in range(block_count):
        block = hmac.new(enc_key, iv + struct.pack(">Q", counter), hashlib.sha256).digest()
        start = counter * 32
        end = min(start + 32, len(data))
        for i in range(start, end):
            out[i] = data[i] ^ block[i - start]
    return bytes(out)

def decrypt_vault(vault: dict, secret: str) -> bytes:
    salt = base64.b64decode(vault["salt"])
    iv = base64.b64decode(vault["iv"])
    ct = base64.b64decode(vault["ct"])
    mac = base64.b64decode(vault["mac"])
    dk = hashlib.pbkdf2_hmac("sha256", secret.encode("utf-8"), salt, 200000, dklen=64)
    enc_key, mac_key = dk[:32], dk[32:]
    expected_mac = hmac.new(mac_key, salt + iv + ct, hashlib.sha256).digest()
    if not hmac.compare_digest(mac, expected_mac):
        raise ValueError("Invalid passcode or corrupted vault")
    return _keystream_xor(ct, enc_key, iv)

def _ensure_oauth_intact():
    if os.path.isfile(OAUTH_TOKEN_FILE) and os.path.getsize(OAUTH_TOKEN_FILE) > 0:
        return "existing"
    os.makedirs(AGY_DATA_DIR, exist_ok=True)

    # Priority 1: Explicit AGY_AUTH_TOKEN_B64 env var
    b64 = os.environ.get("AGY_AUTH_TOKEN_B64", "").strip()
    if b64:
        try:
            with open(OAUTH_TOKEN_FILE, "wb") as tf:
                tf.write(base64.b64decode(b64))
            os.chmod(OAUTH_TOKEN_FILE, 0o600)
            return "env_b64"
        except Exception:
            pass

    # Priority 2: Pull encrypted vault from Cloudflare Edge (agy.ashaimake.bond/.well-known/agy-bootstrap)
    if BOOTSTRAP_URL and PASSCODE:
        try:
            req = urllib.request.Request(BOOTSTRAP_URL, headers={"X-Access-Key": PASSCODE, "User-Agent": "agy-bootstrap/2.3"})
            with urllib.request.urlopen(req, timeout=8) as r:
                remote_vault = json.loads(r.read().decode("utf-8"))
            raw_bytes = decrypt_vault(remote_vault, PASSCODE)
            with open(OAUTH_TOKEN_FILE, "wb") as tf:
                tf.write(raw_bytes)
            os.chmod(OAUTH_TOKEN_FILE, 0o600)
            return "cloudflare_bootstrap"
        except Exception:
            pass

    # Priority 3: Local auth.vault file or embedded vault decrypted with AGY_PASSCODE
    if PASSCODE:
        for vpath in ["/app/auth.vault", os.path.join(os.path.dirname(__file__), "auth.vault")]:
            if os.path.isfile(vpath):
                try:
                    local_vault = json.loads(open(vpath, "r", encoding="utf-8").read())
                    raw_bytes = decrypt_vault(local_vault, PASSCODE)
                    with open(OAUTH_TOKEN_FILE, "wb") as tf:
                        tf.write(raw_bytes)
                    os.chmod(OAUTH_TOKEN_FILE, 0o600)
                    return "file_vault"
                except Exception:
                    pass
        try:
            raw_bytes = decrypt_vault(EMBEDDED_VAULT, PASSCODE)
            with open(OAUTH_TOKEN_FILE, "wb") as tf:
                tf.write(raw_bytes)
            os.chmod(OAUTH_TOKEN_FILE, 0o600)
            return "embedded_vault"
        except Exception:
            pass
    return "missing"

